package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class Node_siblingNodes_TriageGen2Test {

    private Node parent;
    private Node child1;
    private Node child2;
    private Node child3;

    @Before
    public void setUp() {
        Document doc = new Document("<div><p>Text1</p><p>Text2</p><p>Text3</p></div>");
        parent = doc.body();
        child1 = parent.childNode(0);
        child2 = parent.childNode(1);
        child3 = parent.childNode(2);
    }

    @Test
    public void testSiblingNodesForFirstChild() {
        List<Node> siblings = child1.siblingNodes();
        assertEquals(2, siblings.size());
        assertEquals(child2, siblings.get(0));
        assertEquals(child3, siblings.get(1));
    }














}

